import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

import com.vaadin.browserless.SpringBrowserlessTest;
import com.vaadin.flow.component.button.Button;
import com.vaadin.flow.component.html.H2;
import com.vaadin.flow.component.html.ListItem;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.textfield.TextField;

@SpringBootTest
class ItemsViewTest extends SpringBrowserlessTest {

    @Test
    void shellShowsTitle() {
        navigate(ItemsView.class);

        Assertions.assertEquals("Item Tracker", find(H2.class).single().getText());
    }

    @Test
    void add_nonBlankValue_appendsItemClearsFieldAndUpdatesCount() {
        navigate(ItemsView.class);

        test(find(TextField.class).withLabel("Item").single()).setValue("Milk");
        test(find(Button.class).withText("Add").single()).click();

        Assertions.assertEquals("Milk", find(ListItem.class).single().getText());
        Assertions.assertEquals("", find(TextField.class).withLabel("Item").single().getValue());
        Assertions.assertEquals("Items: 1", find(Span.class).withText("Items: 1").single().getText());
    }

    @Test
    void add_blankValue_addsNothingAndMarksFieldInvalid() {
        navigate(ItemsView.class);

        TextField field = find(TextField.class).withLabel("Item").single();
        test(field).setValue("   ");
        test(find(Button.class).withText("Add").single()).click();

        Assertions.assertEquals(0, find(ListItem.class).all().size());
        Assertions.assertTrue(field.isInvalid());
        Assertions.assertEquals("Items: 0", find(Span.class).withText("Items: 0").single().getText());
    }

    @Test
    void add_sameTextTwice_createsTwoItems() {
        navigate(ItemsView.class);

        Button add = find(Button.class).withText("Add").single();
        TextField field = find(TextField.class).withLabel("Item").single();
        test(field).setValue("Eggs");
        test(add).click();
        test(field).setValue("Eggs");
        test(add).click();

        Assertions.assertEquals(2, find(ListItem.class).all().size());
        Assertions.assertEquals("Items: 2", find(Span.class).withText("Items: 2").single().getText());
    }

    @Test
    void clear_removesAllItems_andItemsCanBeAddedAgain() {
        navigate(ItemsView.class);

        TextField field = find(TextField.class).withLabel("Item").single();
        Button add = find(Button.class).withText("Add").single();
        test(field).setValue("Milk");
        test(add).click();
        test(field).setValue("Bread");
        test(add).click();

        test(find(Button.class).withText("Clear").single()).click();

        Assertions.assertEquals(0, find(ListItem.class).all().size());
        Assertions.assertEquals("Items: 0", find(Span.class).withText("Items: 0").single().getText());

        test(field).setValue("Tea");
        test(add).click();
        Assertions.assertEquals("Tea", find(ListItem.class).single().getText());
        Assertions.assertEquals("Items: 1", find(Span.class).withText("Items: 1").single().getText());
    }
}
